const proposed_dates = $('Get Proposed Dates (Accept)').all()
  .filter(r => r.json?.fields?.proposed_interview_date)
  .map(r => ({
    json: {
      start: { dateTime: r.json.fields.proposed_interview_date },
      end: { dateTime: r.json.fields.proposed_interview_end }
    }
  }));

const events = [...$input.all(), ...proposed_dates];

const proposed =
  ($('Get Candidate (Accept)').first()?.json?.fields?.proposed_interview_date || '')
    .trim() || null;

const WORK_START = 10,
      WORK_END = 18,
      DUR = 60,
      BUF = 15,
      TOTAL = 75;

const now = new Date();

const EGY = 3 * 60 * 60 * 1000;

function safeDate(v) {

  if (!v || typeof v !== 'string') {
    return null;
  }

  const clean = v.trim();

  if (!clean) {
    return null;
  }

  const d = new Date(clean);

  return isNaN(d.getTime()) ? null : d;
}

function toEgy(d) {

  if (!d || isNaN(d.getTime())) {
    throw new Error(`Invalid date in toEgy(): ${d}`);
  }

  return new Date(d.getTime() + EGY);
}

function egyDate(d) {

  if (!d || isNaN(d.getTime())) {
    throw new Error(`Invalid date in egyDate(): ${d}`);
  }

  const e = toEgy(d);

  return e.toISOString().slice(0,10);
}

function getTime(t) {

  const d = new Date(t?.dateTime || t);

  return isNaN(d.getTime()) ? null : d;
}

const AR_DAYS = [
  'الأحد','الاثنين','الثلاثاء',
  'الأربعاء','الخميس','الجمعة','السبت'
];

const AR_MON = [
  'يناير','فبراير','مارس','أبريل',
  'مايو','يونيو','يوليو','أغسطس',
  'سبتمبر','أكتوبر','نوفمبر','ديسمبر'
];

function readable(d) {
  const e = toEgy(d);
  const hh = String(e.getUTCHours()).padStart(2, '0');
  const mm = String(e.getUTCMinutes()).padStart(2, '0');
  return AR_DAYS[e.getUTCDay()] + ' ' + e.getUTCDate() + ' ' + AR_MON[e.getUTCMonth()] + ' \u0627\u0644\u0633\u0627\u0639\u0629 ' + hh + ':' + mm;
}


// =======================================
// start date
// =======================================

let startBase = now;

if (proposed) {

  const p = safeDate(proposed);

  if (!p) {
    throw new Error(`Invalid proposed date: ${proposed}`);
  }

  startBase = p;
}

startBase = new Date(Math.max(startBase.getTime(), now.getTime()));


// =======================================
// collect all possible slots
// =======================================

const possible = [];

for (let day = 0; day < 14; day++) {

  const d = new Date(
    startBase.getTime() + day * 86400000
  );

  if (isNaN(d.getTime())) {
    throw new Error(`Invalid d at day ${day}`);
  }

  const wd = toEgy(d).getUTCDay();

  if (wd === 5 || wd === 6) continue;

  const ds = egyDate(d);

  let cur = new Date(
    `${ds}T${String(WORK_START-3).padStart(2,'0')}:00:00Z`
  );

  const wEnd = new Date(
    `${ds}T${String(WORK_END-3).padStart(2,'0')}:00:00Z`
  );

  if (isNaN(cur.getTime()) || isNaN(wEnd.getTime())) {
    throw new Error(`Invalid work hours date for ds=${ds}`);
  }

  while (cur < wEnd) {

    const iEnd = new Date(
      cur.getTime() + DUR * 60000
    );

    const bEnd = new Date(
      cur.getTime() + TOTAL * 60000
    );

    if (iEnd > wEnd) break;

    if (cur <= now) {
      cur = bEnd;
      continue;
    }

    let ok = true;

    for (const item of events) {

      const ev = item.json;

      if (!ev.start || !ev.end) continue;

      const es = getTime(ev.start);
      const eeBase = getTime(ev.end);

      if (!es || !eeBase) continue;

      const ee = new Date(
        eeBase.getTime() + BUF * 60000
      );

      if (cur < ee && bEnd > es) {
        ok = false;
        break;
      }
    }

    if (ok) {

      possible.push({
        start: cur.toISOString(),
        end: iEnd.toISOString(),
        readable: readable(cur)
      });
    }

    cur = bEnd;
  }
}


// =======================================
// next slot
// =======================================

if (possible.length > 0) {

  const slot = possible[0];

  return [{ json: slot }];
}


// =======================================
// no slot
// =======================================

return [{
  json: {
    error: 'no_slot',
    message: 'No available slots'
  }
}];

