const proposedAsEvents = proposed
  .filter(r =>
    r.json.fields.proposed_interview_date &&
    r.json.fields.proposed_interview_end
  )
  .map(r => ({
    json: {
      start: {
        dateTime: r.json.fields.proposed_interview_date
      },
      end: {
        dateTime: r.json.fields.proposed_interview_end
      }
    }
  }));

const allBlocked = [...calendarEvents, ...proposedAsEvents];

