const slots = [];
const usedDays = new Set();

for (let day = 0; day < 14 && slots.length < 3; day++) {

  const d = new Date(now.getTime() + day * 86400000);

  const wd = toEgy(d).getUTCDay();

  // Friday + Saturday
  if (wd === 5 || wd === 6) continue;

  const ds = egyDate(d);

  if (usedDays.has(ds)) continue;

  const hours = [10,11,12,13,14,15,16];

  for (const h of hours) {

    const cur = new Date(
      `${ds}T${String(h - 3).padStart(2,'0')}:00:00Z`
    );

    const iEnd = new Date(cur.getTime() + DUR * 60000);

    const bEnd = new Date(cur.getTime() + TOTAL * 60000);

    const wEnd = new Date(
      `${ds}T${String(WORK_END - 3).padStart(2,'0')}:00:00Z`
    );

    if (iEnd > wEnd || cur <= now) continue;

    let ok = true;

    for (const item of allBlocked) {

      const ev = item.json;

      if (!ev.start || !ev.end) continue;

      const es = getTime(ev.start);

      const ee = new Date(
        getTime(ev.end).getTime() + BUF * 60000
      );

      // overlap check
      if (cur < ee && bEnd > es) {
        ok = false;
        break;
      }
    }

    if (ok) {

      slots.push({
        start: cur.toISOString(),
        end: iEnd.toISOString(),
        readable: readable(cur)
      });

      usedDays.add(ds);

      break;
    }
  }
}

return [
  {
    json: {
      slots
    }
  }
];

