      if (cur < ee && bEnd > es) { ok = false; break; }
    }

    if (ok) {
      slots.push({ start: cur.toISOString(), end: iEnd.toISOString(), readable: readable(cur) });
      usedDays.add(ds);
      break;
    }

    cur = bEnd;
  }
}

return [{ json: { slots } }];

