const start = q.start;
const end = q.end;

function parseSlotList(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.map(String).filter(Boolean);
  const text = String(value).trim();
  if (!text) return [];
  try {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed)) return parsed.map(item => typeof item === 'string' ? item : item?.start).filter(Boolean);
  } catch (e) {}
  return text.split(',').map(s => s.trim()).filter(Boolean);
}

function sameInstant(a, b) {
  const da = new Date(a);
  const db = new Date(b);
  return !isNaN(da) && !isNaN(db) && da.getTime() === db.getTime();
}

function getTime(t) {
  const d = new Date(t?.dateTime || t);
  return isNaN(d.getTime()) ? null : d;
}

function fail(code, message) {
  return [{ json: { valid: false, code, message } }];
}

const selectedStart = new Date(start);
const selectedEnd = new Date(end);
if (!start || !end || isNaN(selectedStart) || isNaN(selectedEnd) || selectedEnd <= selectedStart) {
  return fail('invalid_slot', 'Invalid slot link. Please open the latest reschedule email and choose again.');
}

if (selectedStart <= new Date()) {
  return fail('past_slot', 'This time has already passed. Please choose another slot.');
}

const allowedStatuses = ['Interview Scheduled', 'Interview Confirmed'];
if (!allowedStatuses.includes(fields.status)) {
  return fail('invalid_status', 'This link can no longer be used. Please contact HR or use the latest email link.');
}

const offeredSlots = parseSlotList(fields.offered_slots);
if (!offeredSlots.some(s => sameInstant(s, start))) {
  return fail('not_offered', 'This slot is no longer available for your link. Please choose one of the latest offered slots.');
}

const blocks = [];
for (const evItem of $('Get Calendar (Web Select Conflict)').all()) {
  const ev = evItem.json || {};
  if (ev.start && ev.end) blocks.push({ start: ev.start, end: ev.end });
}
for (const rec of $('Get Proposed Dates (Web Select Conflict)').all()) {
  const f = rec.json?.fields || {};
  if (f.proposed_interview_date) {
    blocks.push({
      start: { dateTime: f.proposed_interview_date },
      end: { dateTime: f.proposed_interview_end || new Date(new Date(f.proposed_interview_date).getTime() + 60 * 60000).toISOString() }
    });
  }
  if (f.interview_date) {
    blocks.push({
      start: { dateTime: f.interview_date },
      end: { dateTime: new Date(new Date(f.interview_date).getTime() + 60 * 60000).toISOString() }
    });
  }
}

const BUFFER_MIN = 15;
const selectedBlockEnd = new Date(selectedEnd.getTime() + BUFFER_MIN * 60000);
for (const block of blocks) {
  const bs = getTime(block.start);
  const beBase = getTime(block.end);
  if (!bs || !beBase) continue;
  const be = new Date(beBase.getTime() + BUFFER_MIN * 60000);
  if (selectedStart < be && selectedBlockEnd > bs) {
    return fail('conflict', 'This time has just been booked. Please go back and choose another slot.');
  }
}

return [{ json: { valid: true, start, end, readable: q.readable || '' } }];
